describe('File Upload - Invalid File Type Error', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="file-input"]').as('fileInput');
    cy.get('[data-testid="upload-button"]').as('uploadButton');
    cy.get('[data-testid="error-message"]').as('errorMessage');
  });

  it('should display error message when uploading an unsupported file type', () => {
    const fileName = 'invalid-file.exe';
    cy.fixture('files/invalid-file.exe', 'binary').then((fileContent) => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: fileName,
        mimeType: 'application/x-msdownload'
      });
    });

    cy.get('@uploadButton').click();

    cy.get('@errorMessage')
      .should('be.visible')
      .and('contain', 'File type not allowed');
  });

  it('should display specific error for multiple invalid file types', () => {
    const invalidFiles = ['document.pdf', 'image.bmp', 'video.mkv'];

    invalidFiles.forEach((fileName) => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from('fake file content'),
        fileName: fileName,
        mimeType: 'application/octet-stream'
      });

      cy.get('@uploadButton').click();

      cy.get('@errorMessage')
        .should('be.visible')
        .and('match', /File type not allowed|Unsupported format/i);

      cy.get('@errorMessage').should('exist');
    });
  });

  it('should allow upload of supported file types without error', () => {
    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from('fake image content'),
      fileName: 'valid-image.jpg',
      mimeType: 'image/jpeg'
    });

    cy.get('@uploadButton').click();

    cy.get('@errorMessage').should('not.exist');
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'File uploaded successfully');
  });

  it('should clear error message when user selects a valid file after invalid attempt', () => {
    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from('fake content'),
      fileName: 'invalid.exe',
      mimeType: 'application/x-msdownload'
    });

    cy.get('@uploadButton').click();
    cy.get('@errorMessage').should('be.visible');

    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from('fake image content'),
      fileName: 'valid.png',
      mimeType: 'image/png'
    });

    cy.get('@errorMessage').should('not.exist');
    cy.get('@uploadButton').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
